using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions; namespace JTradeERP.Application.Features.MasterData.Categories.DeactivateCategory; public sealed class DeactivateCategoryHandler(IApplicationDbContext db) : IRequestHandler<DeactivateCategoryCommand, DeactivateCategoryResponse> { public async Task<DeactivateCategoryResponse> Handle(DeactivateCategoryCommand r,CancellationToken ct){var e=db.Categories.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Category not found.");e.Deactivate();await db.SaveChangesAsync(ct);return new(e.Id,e.Name,e.IsActive);} }
